import { createClient } from 'https://esm.sh/@supabase/supabase-js@2.50.0';

const API_BASE_URL = 'https://api.avantio.pro/pms/v1';
const INCIDENT_STARTED_AT = '2026-07-26T13:00:00Z';
const PROBE_TIMEOUT_MS = 2000;

async function probe(token: string, path: string) {
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), PROBE_TIMEOUT_MS);
  try {
    const response = await fetch(`${API_BASE_URL}${path}`, {
      headers: {
        accept: 'application/json',
        'X-Avantio-Auth': token.replace(/^["'\s]+|["'\s]+$/g, ''),
      },
      signal: controller.signal,
    });
    return { ok: response.ok, status: response.status };
  } catch (error) {
    return {
      ok: false,
      status: error instanceof Error && error.name === 'AbortError' ? 'timeout' : 'network_error',
    };
  } finally {
    clearTimeout(timeout);
  }
}

Deno.serve(async () => {
  const supabaseUrl = Deno.env.get('SUPABASE_URL') ?? '';
  const serviceKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '';
  const avantioToken = Deno.env.get('AVANTIO_API_TOKEN') ?? '';
  if (!supabaseUrl || !serviceKey || !avantioToken) {
    return Response.json({ status: 'configuration_error' }, { status: 500 });
  }

  const supabase = createClient(supabaseUrl, serviceKey);
  const { data: recovered } = await supabase
    .from('avantio_sync_logs')
    .select('id, sync_started_at')
    .eq('status', 'completed')
    .gte('sync_started_at', INCIDENT_STARTED_AT)
    .order('sync_started_at', { ascending: false })
    .limit(1)
    .maybeSingle();
  if (recovered) {
    return Response.json({ status: 'already_recovered', syncLogId: recovered.id });
  }

  const thirtyMinutesAgo = new Date(Date.now() - 30 * 60 * 1000).toISOString();
  const { data: running } = await supabase
    .from('avantio_sync_logs')
    .select('id')
    .eq('status', 'running')
    .gte('sync_started_at', thirtyMinutesAgo)
    .limit(1)
    .maybeSingle();
  if (running) {
    return Response.json({ status: 'sync_already_running', syncLogId: running.id });
  }

  const [listProbe, accommodationProbe] = await Promise.all([
    probe(avantioToken, '/bookings?limit=1'),
    probe(avantioToken, '/accommodations/774600'),
  ]);
  if (!listProbe.ok || !accommodationProbe.ok) {
    return Response.json({ status: 'provider_unhealthy', listProbe, accommodationProbe });
  }

  const trigger = await fetch(`${supabaseUrl}/functions/v1/avantio-sync`, {
    method: 'POST',
    headers: {
      authorization: `Bearer ${serviceKey}`,
      apikey: serviceKey,
      'content-type': 'application/json',
    },
    body: JSON.stringify({
      triggered_by: 'incident_recovery',
      schedule_name: 'avantio-health-recovery',
      source: 'provider-health-gate',
    }),
  });
  const triggerBody = await trigger.text();
  return Response.json({
    status: trigger.ok ? 'recovery_triggered' : 'trigger_failed',
    triggerStatus: trigger.status,
    triggerBody: triggerBody.slice(0, 500),
  }, { status: trigger.ok ? 200 : 502 });
});
